    def test_disabled_mqtt_does_not_connect_or_publish(self):
        """Keep a broker configured but do no MQTT work while MQTT is disabled."""
        clock = types.SimpleNamespace(ticks_ms=lambda: 100000,
                                      ticks_add=lambda value, delta: value + delta,
                                      ticks_diff=lambda first, second: first - second)
        self.lan.isconnected.return_value = True
        mqtt_client = Mock()
        config = dict(web.DEFAULT_CONFIG, mqtt_enabled=False, mqtt_server="broker.local")
        with patch.dict(self.Device.__init__.__globals__, {"time": clock, "MQTTClient": mqtt_client}):
            device = self.Device(config, self.lan, None)
