            with patch.object(web, "CONFIG_FILE", os.path.join(directory, "config.json")):
                legacy = web.DEFAULT_CONFIG.copy()
                legacy.pop("mqtt_enabled", None)
                legacy["mqtt_server"] = "broker.local"
